export class LruCache extends Map {
    #maxSize;
    #currentSize = 0;
    constructor(maxSize, entries = []) {
        super();
        this.#maxSize = maxSize;
        for (const [key, value] of entries) {
            this.set(key, value);
        }
    }
    get(key) {
        const res = super.get(key);
        if (res !== undefined) {
            // update order so key is most recent
            super.delete(key);
            super.set(key, res);
        }
        return res;
    }
    set(key, value) {
        const existing = super.get(key);
        if (existing === undefined) {
            this.#currentSize += key.length; // adding a new key
        }
        else if (existing !== null) {
            this.#currentSize -= existing.byteLength; // removing old value
        }
        if (value !== null) {
            this.#currentSize += value.byteLength;
        }
        // delete existing value
        super.delete(key);
        // evict down to desired size
        let entry;
        while (this.#currentSize > this.#maxSize &&
            (entry = this.entries().next().value)) {
            const [oldestKey, oldestValue] = entry;
            super.delete(oldestKey);
            this.#currentSize -= oldestKey.length;
            if (oldestValue !== null) {
                this.#currentSize -= oldestValue.byteLength;
            }
        }
        // finally insert new key and return
        super.set(key, value);
        return this;
    }
    delete(key) {
        const value = super.get(key);
        if (value === undefined) {
            return false;
        }
        super.delete(key);
        if (value !== null) {
            this.#currentSize -= value.byteLength;
        }
        this.#currentSize -= key.length;
        return true;
    }
    clear() {
        super.clear();
        this.#currentSize = 0;
    }
}
